"use strict";

const ts = require("typescript");
const pkg = require("../package.json");

const version = pkg.version;

function toCompilerOptions(options = {}) {
  const loader = options.loader || "ts";
  const isJsx = loader === "jsx" || loader === "tsx";

  return {
    target: ts.ScriptTarget.ESNext,
    module: ts.ModuleKind.ESNext,
    jsx: isJsx ? ts.JsxEmit.Preserve : ts.JsxEmit.Preserve,
    sourceMap: Boolean(options.sourcemap),
    inlineSources: Boolean(options.sourcemap),
    importHelpers: false,
    noEmitHelpers: false,
    esModuleInterop: true,
    allowJs: true,
    resolveJsonModule: true,
    verbatimModuleSyntax: true,
  };
}

function normalizeSourceFile(options = {}) {
  return options.sourcefile || "input.ts";
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function stripQuotes(text) {
  if (typeof text !== "string") return text;
  if ((text.startsWith("\"") && text.endsWith("\"")) || (text.startsWith("'") && text.endsWith("'"))) {
    return text.slice(1, -1);
  }
  return text;
}

function applyDefines(code, define = {}) {
  const merged = {
    "process.env.NODE_ENV": "\"production\"",
    ...define,
  };

  const entries = Object.entries(merged)
    .map(([key, value]) => [key, typeof value === "string" ? value : String(value)])
    .sort((a, b) => b[0].length - a[0].length);

  let output = code;
  for (const [key, rawValue] of entries) {
    const value = stripQuotes(rawValue);
    const replacement = /^(true|false|[0-9]+(?:\.[0-9]+)?|null|undefined)$/.test(value)
      ? value
      : JSON.stringify(value);
    output = output.replace(new RegExp(escapeRegExp(key), "g"), replacement);
  }
  return output;
}

function transformSync(code, options = {}) {
  if (options.loader === "css") {
    return {
      code,
      map: "",
      warnings: [],
    };
  }

  const codeWithDefines = applyDefines(code, options.define);
  const result = ts.transpileModule(codeWithDefines, {
    compilerOptions: toCompilerOptions(options),
    fileName: normalizeSourceFile(options),
    reportDiagnostics: false,
  });

  return {
    code: result.outputText,
    map: result.sourceMapText || "",
    warnings: [],
  };
}

async function transform(code, options = {}) {
  return transformSync(code, options);
}

function formatMessages(messages) {
  return (messages || []).map((message) => {
    if (typeof message === "string") return message;
    if (message && typeof message.text === "string") return message.text;
    return String(message);
  });
}

function formatMessagesSync(messages) {
  return formatMessages(messages);
}

function analyzeMetafile() {
  return "";
}

function analyzeMetafileSync() {
  return "";
}

async function build() {
  throw new Error("esbuild build is not available in this workspace");
}

function buildSync() {
  throw new Error("esbuild build is not available in this workspace");
}

async function context() {
  throw new Error("esbuild context is not available in this workspace");
}

async function initialize() {}

async function stop() {}

exports.analyzeMetafile = analyzeMetafile;
exports.analyzeMetafileSync = analyzeMetafileSync;
exports.build = build;
exports.buildSync = buildSync;
exports.context = context;
exports.default = {
  analyzeMetafile,
  analyzeMetafileSync,
  build,
  buildSync,
  context,
  formatMessages,
  formatMessagesSync,
  initialize,
  stop,
  transform,
  transformSync,
  version,
};
exports.formatMessages = formatMessages;
exports.formatMessagesSync = formatMessagesSync;
exports.initialize = initialize;
exports.stop = stop;
exports.transform = transform;
exports.transformSync = transformSync;
exports.version = version;
